export function getAllFormulas(): FormulaItem[] {
  return FORMULA_CATALOG;
}

export function getFormulasBySubject(subjectId: string): FormulaItem[] {
  return FORMULA_CATALOG.filter((f) => f.subjectId === subjectId);
}

export function getSubjectMeta(subjectId: string): SubjectFormulaMeta | undefined {
  return SUBJECT_METADATA[subjectId];
}
